/* ── Kami parchment tokens ─────────────────────────────────────────────── */
:root{
  --paper:#f5f4ed;
  --paper-tint:#efeee5;
  --ink:#1f1d18;
  --ink-soft:#6b665b;
  --rule:#d4d1c5;
